/**
 * Fallback stub for Wails v3 generated bindings when running in unit tests or browser mode
 * where bindings have not yet been generated by the Wails CLI.
 */
export const MinimizeWindow = (): Promise<void> => Promise.resolve();
/** No-op stub of the Wails `MinimizeWindow` binding (see file header for when used). */
export const MaximizeWindow = (): Promise<void> => Promise.resolve();
/** No-op stub of the Wails `CloseWindow` binding (see file header for when used). */
export const CloseWindow = (): Promise<void> => Promise.resolve();
/** Stub returning `false` (no simulation window) for the Wails `OpenSimulationWindow` binding. */
export const OpenSimulationWindow = (): Promise<boolean> => Promise.resolve(false);
/** Stub that resolves immediately for the Wails `OpenDevTools` binding (no-op without a real backend). */
export const OpenDevTools = (): Promise<void> => Promise.resolve();
/** Stub returning `false` for the Wails `CloseSimulationWindow` binding. */
export const CloseSimulationWindow = (): Promise<boolean> => Promise.resolve(false);
/** Stub for the Wails `OpenSidebarWindow(side)` binding; always resolves `false` in fallback. */
export const OpenSidebarWindow = (_side: string): Promise<boolean> => Promise.resolve(false);
/** Stub for the Wails `CloseSidebarWindow(side)` binding; always resolves `false` in fallback. */
export const CloseSidebarWindow = (_side: string): Promise<boolean> => Promise.resolve(false);
/** Stub for the Wails `StartSimulation(speed?)` binding; always resolves `true`. */
export const StartSimulation = (_speed?: number): Promise<boolean> => Promise.resolve(true);
/** Stub for the Wails `PauseSimulation` binding; always resolves `true`. */
export const PauseSimulation = (): Promise<boolean> => Promise.resolve(true);
/** Stub for the Wails `ResumeSimulation` binding; always resolves `true`. */
export const ResumeSimulation = (): Promise<boolean> => Promise.resolve(true);
/** Stub for the Wails `StopSimulation` binding; always resolves `true`. */
export const StopSimulation = (): Promise<boolean> => Promise.resolve(true);
/** Stub for the Wails `SetSimulationSpeed(speed)` binding; always resolves `true`. */
export const SetSimulationSpeed = (_speed: number): Promise<boolean> => Promise.resolve(true);
/** Stub for the Wails `BroadcastSimulationSnapshot(snapshotJson)` binding; always resolves `true`. */
export const BroadcastSimulationSnapshot = (_snapshot: string): Promise<boolean> => Promise.resolve(true);
/** Stub for the Wails `GetSimulationSnapshot` binding; always resolves the empty snapshot `'{}'`. */
export const GetSimulationSnapshot = (): Promise<string> => Promise.resolve('{}');
/** Stub for the Wails `Greet(name)` binding; always resolves to the empty string. */
export const Greet = (_name: string): Promise<string> => Promise.resolve('');
/** Stub for the Wails `GetSystemResources` binding; always resolves `{}`. */
export const GetSystemResources = (): Promise<any> => Promise.resolve({});
